"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def rotateMatrix(matrix, N):
    # Transpose
    for i in range(0, N):
        for j in range((i + 1), N):
            temp_var = matrix[i][j]
            matrix[i][j] = matrix[j][i]
            matrix[j][i] = temp_var
            # Reverse each row
    for i in range(0, N):
        for j in range(0, (N // 2)):
            temp_var = matrix[i][j]
            matrix[i][j] = matrix[i][((N - 1) - j)]
            matrix[i][((N - 1) - j)] = temp_var
print(rotateMatrix([[1, 2, 3], [4, 5, 6], [7, 8, 9]], 3))